import * as React from "react"

function HamburgerMenuWithOpencloseAnimation({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="hamburger-menu-with-openclose-animation"
      className={className}
      {...props}
    >
      <div className="min-h-screen bg-gray-100 flex flex-col justify-center">
          <div className="relative py-3 sm:max-w-xl mx-auto">
              <nav>
                  <button className="w-14 h-14 relative focus:outline-none bg-teal-600 rounded">
                      <div className="block w-5 absolute left-6 top-1/2   transform  -translate-x-1/2 -translate-y-1/2">
                          <span  className="block absolute h-0.5 w-7 text-white bg-current transform transition duration-500 ease-in-out"></span>
                          <span  className="block absolute  h-0.5 w-5 text-white bg-current   transform transition duration-500 ease-in-out"></span>
                          <span  className="block absolute  h-0.5 w-7 text-white bg-current transform  transition duration-500 ease-in-out"></span>
                      </div>
                  </button>
              </nav>
          </div>
      </div>
    </div>
  )
}

export { HamburgerMenuWithOpencloseAnimation }
